void SpawnAsteroid()
{
    Vector3 pos = Random.onUnitSphere * spawnRadius;
    float size = Random.Range(0.5f, 2.5f);

    GameObject ast = Instantiate(asteroidPrefab, pos, Random.rotation);
    ast.transform.localScale = Vector3.one * size;

    Rigidbody rb = ast.GetComponent<Rigidbody>();
    rb.AddForce(Random.onUnitSphere * Random.Range(5,15), ForceMode.Impulse);
}

public void OnSelectEntered(SelectEnterEventArgs args)
{
    grabbed = true;
    rb.isKinematic = true;
}

public void OnSelectExited(SelectExitEventArgs args)
{
    grabbed = false;
    rb.isKinematic = false;
}

void Update()
{
    switch(state)
    {
        case Idle:
            LookForPlayer();
            break;

        case Chase:
            MoveTowardPlayer();
            break;

        case Attack:
            TryShoot();
            break;
    }
}

void Shoot()
{
    Ray ray = new Ray(transform.position, transform.forward);

    if (Physics.Raycast(ray, out var hit, 50f))
    {
        Debug.Log($"Hit {hit.collider.name}");
    }
}

public class StepGuide : MonoBehaviour
{
    public List<TrainingStep> steps;
    private int currentStep = 0;

    void CheckStepCompletion()
    {
        if (steps[currentStep].IsCompleted())
        {
            currentStep++;
            ShowNextInstruction();
        }
    }
}

bool ValidateHandPose(HandPose required)
{
    float similarity = Vector3.Dot(
        currentPose.palmNormal,
        required.palmNormal
    );

    return similarity > 0.95f;
}

IEnumerator Letters()
{
    dialogText.text = "";

    if (queue.Count != 0)
    { 
        string sentence = queue.Dequeue();

        foreach (char letter in sentence)
        { 
            dialogText.text += letter;
            yield return new WaitForSeconds(letterDelay);
        }
    }
}

private void Update()
{
    if (!MaskPickup.MinigamingIt)
    {
        Vector3 move = transform.right * Input.GetAxis("Horizontal") + transform.forward * Input.GetAxis("Vertical");
        cc.Move(move * speed * Time.deltaTime);
        if (cc.isGrounded && velocity.y < 0)
        {
            velocity.y = -2;
        }
        velocity.y += gravity * Time.deltaTime;
        cc.Move(velocity * Time.deltaTime);
    }

    if ((Input.GetKey(KeyCode.W) || Input.GetKey(KeyCode.A) || Input.GetKey(KeyCode.S) || Input.GetKey(KeyCode.D)) && !MaskPickup.MinigamingIt)
    {
        walking = true;
    }
    else
    {
        walking = false;
    }

    if (walking)
    {
        if (!walkAudio.isPlaying)
        {
            walkAudio.Play();
            walkAudio.pitch = Random.Range(.75f, 1f);
        }
    }
    else
    {
        walkAudio.Stop();
    }
}

private void TurnFourHandler()
{
    originalPlayerHealth = playerHealth.currentHealth;
    int baseDamage = 5;
    int finalDamage;
    finalDamage = DamageCalc(baseDamage);
    intentText.text = finalDamage.ToString() + ", " + "buff, " + "Debuff";
    if (TurnManager.turnManager.turnCounter > originalTurnCount)
    {
        enemyHealth.GainShield(10);
        playerHealth.TakeDamage(finalDamage);
        CheckForBleed();
        StatusManager.statusManager.playerVulnerableStacks += 2;
        StatusManager.statusManager.enemyStrength += 1;
        originalTurnCount = TurnManager.turnManager.turnCounter;
        currentState = TurnCycleState.Turn5;
    }
}

public class BaseEnemyBehavior : MonoBehaviour
{
    public enum TurnCycleState
    {
        Turn1,
        Turn2,
        Turn3,
        Turn4,
        Turn5,
        Turn6,
    }
    [SerializeField] protected TextMeshProUGUI intentText;
    public TurnCycleState currentState = TurnCycleState.Turn1;
    protected int originalTurnCount;
    protected HealthBar playerHealth;
    protected HealthBar enemyHealth;

    virtual public void HandleStageTransition()
    {
        switch (currentState)
        {
            case TurnCycleState.Turn1:
                TurnOneHandler();
                break;
            case TurnCycleState.Turn2:
                TurnTwoHandler();
                break;
            case TurnCycleState.Turn3:
                TurnThreeHandler();
                break;
        }
    }

    virtual protected void Awake()
    {
        GameObject player = GameObject.FindGameObjectWithTag("Player");
        playerHealth = player.GetComponent<HealthBar>();
        enemyHealth = GetComponent<HealthBar>();
    }

    private void Start()
    {
        if (StatusManager.statusManager != null)
        {
            StatusManager.statusManager.enemyHealthBar = this.GetComponent<HealthBar>();
        }
    }

    virtual protected void Update()
    {
        HandleStageTransition();
    }

    virtual public void TurnOneHandler()
    {
        int baseDamage = 10;
        int finalDamage;
        finalDamage = DamageCalc(baseDamage);
        intentText.text = finalDamage.ToString();
        if (TurnManager.turnManager.turnCounter > originalTurnCount)
        {
            playerHealth.TakeDamage(finalDamage);
            originalTurnCount = TurnManager.turnManager.turnCounter;
            currentState = TurnCycleState.Turn2;
        }
    }

    virtual public void TurnTwoHandler()
    {
        int baseDamage = 6;
        int finalDamage;
        finalDamage = DamageCalc(baseDamage);
        intentText.text = finalDamage.ToString() + ", " + "Shield";
        if (TurnManager.turnManager.turnCounter > originalTurnCount)
        {
            playerHealth.TakeDamage(finalDamage);
            enemyHealth.GainShield(10);
            originalTurnCount = TurnManager.turnManager.turnCounter;
            currentState = TurnCycleState.Turn3;
        }
    }

    virtual public void TurnThreeHandler()
    {
        int baseDamage = 6;
        int finalDamage;
        finalDamage = DamageCalc(baseDamage);
        intentText.text = finalDamage.ToString() + ", " + "Debuff";
        if (TurnManager.turnManager.turnCounter > originalTurnCount)
        {
            playerHealth.TakeDamage(finalDamage);
            StatusManager.statusManager.playerWeakenStacks++;
            originalTurnCount = TurnManager.turnManager.turnCounter;
            currentState = TurnCycleState.Turn1;
        }
    }

    protected int DamageCalc(int damage)
    {
        damage += StatusManager.statusManager.enemyStrength;
        if (StatusManager.statusManager.playerVulnerableStacks > 0)
        {
            Debug.Log("vuln");
            damage = Mathf.CeilToInt(damage * 1.5f);
        }
        return damage;
    }
}
